import { useState, useEffect, useRef } from 'react';

function Counter(): JSX.Element {
  const [count, setCount] = useState(0);
  const prevCountRef = useRef<number>(0);

  // Store previous value after each render
  useEffect(() => {
    prevCountRef.current = count;
  });

  const prevCount = prevCountRef.current;
  const difference = count - prevCount;

  return (
    <div>
      <p>Current: {count}</p>
      <p>Previous: {prevCount}</p>
      <p>Difference: {difference}</p>
      <button onClick={() => setCount(c => c + Math.floor(Math.random() * 10))}>
        Add Random
      </button>
    </div>
  );
}

import { forwardRef, useRef, useImperativeHandle, useState } from 'react';

// Define what methods the parent can call via ref
interface FancyInputHandle {
  focus: () => void;
  clear: () => void;
  getValue: () => string;
}

interface FancyInputProps {
  label: string;
}

const FancyInput = forwardRef<FancyInputHandle, FancyInputProps>(
  ({ label }, ref) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const [value, setValue] = useState('');

    useImperativeHandle(ref, () => ({
      focus: () => inputRef.current?.focus(),
      clear: () => setValue(''),
      getValue: () => value
    }), [value]);

    return (
      <label>
        {label}
        <input
          ref={inputRef}
          value={value}
          onChange={e => setValue(e.target.value)}
        />
      </label>
    );
  }
);

FancyInput.displayName = 'FancyInput';

// Parent usage
function Parent(): JSX.Element {
  const fancyRef = useRef<FancyInputHandle>(null);

  return (
    <div>
      <FancyInput ref={fancyRef} label="Username" />
      <button onClick={() => fancyRef.current?.focus()}>Focus</button>
      <button onClick={() => fancyRef.current?.clear()}>Clear</button>
