import { useState, useMemo } from 'react';

interface Order {
  id: string;
  amount: number;
  date: string;
  status: 'pending' | 'completed' | 'cancelled';
}

function OrderDashboard({ orders }: { orders: Order[] }): JSX.Element {
  const [dateRange, setDateRange] = useState<'7d' | '30d' | '90d'>('30d');

  // Expensive computation: memoize to avoid recalculating on every render
  const analytics = useMemo(() => {
    console.log('Computing analytics...');

    const filtered = orders.filter(order => {
      const days = parseInt(dateRange);
      const orderDate = new Date(order.date);
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - days);
      return orderDate >= cutoff;
    });

    const totalRevenue = filtered
      .filter(o => o.status === 'completed')
      .reduce((sum, o) => sum + o.amount, 0);

    const pendingCount = filtered.filter(o => o.status === 'pending').length;
    const averageOrder = filtered.length > 0 ? totalRevenue / filtered.length : 0;

    // Sort by amount descending
    const topOrders = [...filtered]
      .sort((a, b) => b.amount - a.amount)
      .slice(0, 5);

    return { totalRevenue, pendingCount, averageOrder, topOrders, totalOrders: filtered.length };
  }, [orders, dateRange]);

  return (
    <div>
      <select value={dateRange} onChange={e => setDateRange(e.target.value as typeof dateRange)}>
        <option value="7d">Last 7 days</option>
        <option value="30d">Last 30 days</option>
        <option value="90d">Last 90 days</option>
      </select>

      <div className="metrics">
        <Metric label="Revenue" value={`$${analytics.totalRevenue.toFixed(2)}`} />
        <Metric label="Pending" value={analytics.pendingCount} />
        <Metric label="Avg Order" value={`$${analytics.averageOrder.toFixed(2)}`} />
      </div>
    </div>
  );
}

