import { create } from 'zustand';
import { devtools, persist } from 'zustand/middleware';

interface UserState {
  user: User | null;
  isLoading: boolean;
  error: string | null;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
}

const useUserStore = create<UserState>()(
  devtools(
    persist(
      (set) => ({
        user: null,
        isLoading: false,
        error: null,

        login: async (email, password) => {
          set({ isLoading: true, error: null });
          try {
            const response = await fetch('/api/login', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ email, password })
            });

            if (!response.ok) throw new Error('Login failed');

            const data = await response.json();
            set({ user: data.user, isLoading: false });
          } catch (err) {
            set({ 
              error: err instanceof Error ? err.message : 'Unknown error',
              isLoading: false 
            });
          }
        },

        logout: () => set({ user: null, error: null }),
      }),
      { name: 'user-storage' } // localStorage key
    ),
    { name: 'UserStore' } // Redux DevTools name
  )
);

// Usage with selectors
function UserProfile(): JSX.Element {
  const user = useUserStore((state) => state.user);
  const isLoading = useUserStore((state) => state.isLoading);

  if (isLoading) return <p>Loading...</p>;
  if (!user) return <p>Not logged in</p>;

  return <div>Welcome, {user.name}!</div>;
}

import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';

interface CartState {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
}

interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

const useCartStore = create<CartState>((set) => ({
  items: [],
  addItem: (item) => set((state) => ({
    items: [...state.items, item]
  })),
  removeItem: (id) => set((state) => ({
    items: state.items.filter((item) => item.id !== id)
  })),
}));

// Computed values with selectors
function CartSummary(): JSX.Element {
  // useShallow prevents re-renders when unrelated state changes
  const { totalItems, totalPrice } = useCartStore(
    useShallow((state) => ({
      totalItems: state.items.reduce((sum, item) => sum + item.quantity, 0),
      totalPrice: state.items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    }))
  );

  return (
    <div className="cart-summary">
      <span>Items: {totalItems}</span>
      <span>Total: ${totalPrice.toFixed(2)}</span>
    </div>
  );
}

import { configureStore, createSlice, PayloadAction } from '@reduxjs/toolkit';

// Define the state shape
interface CounterState {
  value: number;
  status: 'idle' | 'loading';
}

const initialState: CounterState = {
  value: 0,
  status: 'idle',
};

// Create a slice: reducers + actions generated automatically
const counterSlice = createSlice({
  name: 'counter',
  initialState,
  reducers: {
    increment: (state) => {
      // Immer allows "mutating" syntax that produces immutable updates
      state.value += 1;
    },
    decrement: (state) => {
      state.value -= 1;
    },
    incrementByAmount: (state, action: PayloadAction<number>) => {
      state.value += action.payload;
    },
    setStatus: (state, action: PayloadAction<'idle' | 'loading'>) => {
      state.status = action.payload;
    },
  },
});

// Auto-generated action creators
export const { increment, decrement, incrementByAmount, setStatus } = counterSlice.actions;

// Create the store
export const store = configureStore({
  reducer: {
    counter: counterSlice.reducer,
  },
});

// TypeScript types for the store
export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

