// hooks/useApiQuery.ts
import { useState, useEffect } from 'react';
import { ApiRequestError } from '@/api/client';

interface UseApiQueryResult<T> {
  data: T | null;
  loading: boolean;
  error: ApiRequestError | null;
  isNetworkError: boolean;
  isClientError: boolean;
  isServerError: boolean;
}

export function useApiQuery<T>(
  fetchFn: () => Promise<T>,
  deps: unknown[] = []
): UseApiQueryResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiRequestError | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchFn()
      .then(result => {
        if (!cancelled) setData(result);
      })
      .catch(err => {
        if (!cancelled) {
          if (err instanceof ApiRequestError) {
            setError(err);
          } else {
            setError(new ApiRequestError('Network error', 'NETWORK_ERROR', 0));
          }
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, deps);

  return {
    data,
    loading,
    error,
    isNetworkError: error?.code === 'NETWORK_ERROR',
    isClientError: (error?.status ?? 0) >= 400 && (error?.status ?? 0) < 500,
    isServerError: (error?.status ?? 0) >= 500,
  };
}

// Usage with error-specific UI
function UserProfile({ userId }: { userId: string }): JSX.Element {
  const { data, loading, error, isNetworkError, isClientError } = useApiQuery(
    () => userService.getById(userId),
    [userId]
  );

  if (loading) return <Skeleton />;
  if (isNetworkError) return <OfflineMessage />;
  if (isClientError) return <NotFound />;
  if (error) return <GenericError error={error} />;

  return <ProfileCard user={data!} />;
}

