// Define typed GraphQL operations
const GET_TODOS = gql`
  query GetTodos {
    todos {
      id
      title
      completed
      createdAt
    }
  }
`;

const TOGGLE_TODO = gql`
  mutation ToggleTodo($id: ID!) {
    toggleTodo(id: $id) {
      id
      completed
    }
  }
`;

// TypeScript interfaces matching the schema
interface Todo {
  id: string;
  title: string;
  completed: boolean;
  createdAt: string;
}

interface GetTodosData {
  todos: Todo[];
}

function TodoList(): JSX.Element {
  const { data, loading, error } = useQuery<GetTodosData>(GET_TODOS);
  const [toggleTodo] = useMutation(TOGGLE_TODO, {
    update(cache, { data: mutationData }) {
      // Update the cache directly for instant UI feedback
      cache.modify({
        fields: {
          todos(existingTodos = []) {
            return existingTodos.map((todo: Todo) =>
              todo.id === mutationData?.toggleTodo.id
                ? { ...todo, completed: mutationData.toggleTodo.completed }
                : todo
            );
          },
        },
      });
    },
  });

  if (loading) return <p>Loading todos...</p>;
  if (error) return <p>Error: {error.message}</p>;

  return (
    <ul>
      {data?.todos.map(todo => (
        <li key={todo.id}>
          <label>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => toggleTodo({ variables: { id: todo.id } })}
            />
            <span className={todo.completed ? 'completed' : ''}>
              {todo.title}
            </span>
          </label>
        </li>
      ))}
    </ul>
  );
}

