import { z } from 'zod';

// Define schemas
const CreateTodoSchema = z.object({
  title: z.string().min(1).max(200),
});

const UpdateTodoSchema = z.object({
  title: z.string().min(1).max(200).optional(),
  completed: z.boolean().optional(),
});

// Infer TypeScript types from schemas
type CreateTodoInput = z.infer<typeof CreateTodoSchema>;
type UpdateTodoInput = z.infer<typeof UpdateTodoSchema>;

// Validation middleware factory
function validateBody<T>(schema: z.ZodSchema<T>) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      res.status(400).json({
        message: 'Validation failed',
        errors: result.error.flatten().fieldErrors,
      });
      return;
    }
    req.body = result.data;
    next();
  };
}

// Apply validation to routes
app.post('/api/todos', validateBody(CreateTodoSchema), (req: Request, res: Response) => {
  // req.body is now typed as CreateTodoInput
  const { title } = req.body as CreateTodoInput;

  const newTodo: Todo = {
    id: Date.now().toString(),
    title,
    completed: false,
    createdAt: new Date().toISOString(),
  };

  todos.push(newTodo);
  res.status(201).json(newTodo);
});

