  }

  const token = jwt.sign(
    { userId: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES_IN }
  );

  res.json({
    token,
    user: { id: user.id, email: user.email, name: user.name },
  });
});

// server/middleware/auth.ts
import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';

interface AuthRequest extends Request {
  user?: { userId: string; email: string };
}

const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key';

export function authMiddleware(
  req: AuthRequest,
  res: Response,
  next: NextFunction
): void {
  const authHeader = req.headers.authorization;

  if (!authHeader?.startsWith('Bearer ')) {
    res.status(401).json({ message: 'No token provided' });
    return;
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, JWT_SECRET) as {
      userId: string;
      email: string;
    };
    req.user = decoded;
    next();
  } catch {
    res.status(401).json({ message: 'Invalid token' });
  }
}

// Apply to protected routes
app.get('/api/me', authMiddleware, (req: AuthRequest, res: Response) => {
  const user = users.find(u => u.id === req.user!.userId);
  if (!user) {
    res.status(404).json({ message: 'User not found' });
    return;
  }
  res.json({ id: user.id, email: user.email, name: user.name });
});

app.get('/api/todos', authMiddleware, (req: AuthRequest, res: Response) => {
  // Only return todos belonging to the authenticated user
  const userTodos = todos.filter(t => t.userId === req.user!.userId);
  res.json(userTodos);
});

// contexts/AuthContext.tsx
import { createContext, useContext, useState, useEffect, ReactNode } from 'react';

interface AuthUser {
  id: string;
  email: string;
  name: string;
}

interface AuthContextType {
  user: AuthUser | null;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, name: string) => Promise<void>;
  logout: () => void;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }): JSX.Element {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check for existing token on mount
    const token = localStorage.getItem('token');
    if (token) {
      fetchUser(token);
    } else {
      setIsLoading(false);
    }
  }, []);

  const fetchUser = async (token: string): Promise<void> => {
    try {
      const res = await fetch('/api/me', {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const userData = await res.json();
        setUser(userData);
      } else {
        localStorage.removeItem('token');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const login = async (email: string, password: string): Promise<void> => {
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });

    if (!res.ok) throw new Error('Login failed');

    const { token, user } = await res.json();
    localStorage.setItem('token', token);
    setUser(user);
  };

  const logout = (): void => {
    localStorage.removeItem('token');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, register: async () => {}, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
}

// server/websocket.ts
import { WebSocketServer, WebSocket } from 'ws';
import { Server } from 'http';

interface ChatMessage {
  id: string;
  userId: string;
  userName: string;
  text: string;
  timestamp: string;
}

export function setupWebSocket(server: Server): void {
  const wss = new WebSocketServer({ server, path: '/ws' });
  const clients = new Map<string, WebSocket>();

  wss.on('connection', (ws: WebSocket, req) => {
    const clientId = Date.now().toString();
    clients.set(clientId, ws);
    console.log(`Client ${clientId} connected. Total: ${clients.size}`);

    // Send welcome message
    ws.send(JSON.stringify({
      type: 'system',
      message: 'Connected to chat server',
    }));

    // Broadcast to all clients
    ws.on('message', (data: Buffer) => {
      try {
        const message: ChatMessage = JSON.parse(data.toString());

        // Broadcast to all connected clients
        clients.forEach((client, id) => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(JSON.stringify({
              type: 'message',
              data: message,
            }));
          }
        });
      } catch (err) {
        ws.send(JSON.stringify({
          type: 'error',
          message: 'Invalid message format',
        }));
      }
    });

    // Remove client on disconnect
    ws.on('close', () => {
      clients.delete(clientId);
      console.log(`Client ${clientId} disconnected. Total: ${clients.size}`);
    });
  });
}

import { useState, useEffect, useRef, useCallback } from 'react';

interface UseWebSocketOptions {
  url: string;
  onMessage?: (data: unknown) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
}

interface UseWebSocketReturn {
  send: (data: unknown) => void;
  isConnected: boolean;
  isConnecting: boolean;
}

export function useWebSocket({
  url,
  onMessage,
  onConnect,
  onDisconnect,
}: UseWebSocketOptions): UseWebSocketReturn {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout>>();

  const connect = useCallback((): void => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;

    setIsConnecting(true);
    const ws = new WebSocket(url);
    wsRef.current = ws;

    ws.onopen = () => {
      setIsConnected(true);
      setIsConnecting(false);
      onConnect?.();
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        onMessage?.(data);
      } catch {
        onMessage?.(event.data);
      }
    };

    ws.onclose = () => {
      setIsConnected(false);
      onDisconnect?.();
      // Reconnect after 3 seconds
      reconnectTimeoutRef.current = setTimeout(connect, 3000);
    };

    ws.onerror = () => {
      ws.close();
    };
  }, [url, onMessage, onConnect, onDisconnect]);

  useEffect(() => {
    connect();
    return () => {
      clearTimeout(reconnectTimeoutRef.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: unknown): void => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  return { send, isConnected, isConnecting };
}

import { useState, useRef } from 'react';
import { useWebSocket } from '@/hooks/useWebSocket';

interface ChatMessage {
  id: string;
  userId: string;
  userName: string;
  text: string;
  timestamp: string;
}

function ChatRoom({ userName }: { userName: string }): JSX.Element {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const { send, isConnected } = useWebSocket({
    url: 'ws://localhost:3001/ws',
    onMessage: (data) => {
      if (data.type === 'message') {
        setMessages(prev => [...prev, data.data as ChatMessage]);
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
      }
    },
  });

  const handleSend = (e: React.FormEvent): void => {
    e.preventDefault();
    if (!inputText.trim() || !isConnected) return;

    const message: ChatMessage = {
      id: Date.now().toString(),
      userId: 'current-user',
      userName,
      text: inputText.trim(),
      timestamp: new Date().toISOString(),
    };

    send(message);
    setInputText('');
  };

  return (
    <div className="chat-room">
      <div className="chat-header">
        <span className={`status ${isConnected ? 'online' : 'offline'}`} />
        {isConnected ? 'Connected' : 'Reconnecting...'}
      </div>

      <div className="messages">
        {messages.map(msg => (
          <div key={msg.id} className="message">
            <span className="author">{msg.userName}</span>
            <span className="text">{msg.text}</span>
            <span className="time">
              {new Date(msg.timestamp).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSend}>
        <input
          value={inputText}
          onChange={e => setInputText(e.target.value)}
          placeholder="Type a message..."
          disabled={!isConnected}
        />
        <button type="submit" disabled={!isConnected}>
          Send
        </button>
      </form>
    </div>
  );
}
